14	namespace Microsoft.Agents.AI;
15	
16	/// <summary>
17	/// A text search context provider that performs a search over external knowledge
18	/// and injects the formatted results into the AI invocation context, or exposes a search tool for on-demand use.
19	/// This provider can be used to enable Retrieval Augmented Generation (RAG) on an agent.
20	/// </summary>
21	/// <remarks>
22	/// <para>
23	/// The provider supports two behaviors controlled via <see cref="TextSearchProviderOptions.SearchTime"/>:
24	/// <list type="bullet">
25	/// <item><description><see cref="TextSearchProviderOptions.TextSearchBehavior.BeforeAIInvoke"/> – Automatically performs a search prior to every AI invocation and injects results as additional messages.</description></item>
26	/// <item><description><see cref="TextSearchProviderOptions.TextSearchBehavior.OnDemandFunctionCalling"/> – Exposes a function tool that the model may invoke to retrieve contextual information when needed.</description></item>
27	/// </list>
28	/// </para>
29	/// <para>
30	/// When <see cref="TextSearchProviderOptions.RecentMessageMemoryLimit"/> is greater than zero the provider will retain the most recent
31	/// user and assistant messages (up to the configured limit) across invocations and prepend them (in chronological order)
32	/// to the current request messages when forming the search input. This can improve search relevance by providing
33	/// multi-turn context to the retrieval layer without permanently altering the conversation history.
34	/// </para>
35	/// <para>
36	/// <strong>Security considerations:</strong> Search results retrieved from external sources are injected into the LLM context and may
37	/// contain adversarial content designed to manipulate LLM behavior via indirect prompt injection. Developers should be aware that:
38	/// <list type="bullet">
39	/// <item><description>The search query may be constructed from user input or LLM-generated content, both of which are untrusted.
40	/// Implementers of the search delegate should validate search inputs and apply appropriate access controls to search results.</description></item>
41	/// <item><description>Retrieved documents are formatted and injected as messages in the AI request context. If the external data source
42	/// is compromised, adversarial content could influence the LLM's responses.</description></item>
43	/// <item><description>When using <see cref="TextSearchProviderOptions.TextSearchBehavior.OnDemandFunctionCalling"/>, the AI model controls
44	/// when and what to search for — the search query text is AI-generated and should be treated as untrusted input by the search implementation.</description></item>
45	/// </list>
46	/// </para>
47	/// </remarks>
48	public sealed class TextSearchProvider : MessageAIContextProvider
49	{
50	    private const string DefaultPluginSearchFunctionName = "Search";
51	    private const string DefaultPluginSearchFunctionDescription = "Allows searching for additional information to help answer the user question.";
52	    private const string DefaultContextPrompt = "## Additional Context\nConsider the following information from source documents when responding to the user:";
53	    private const string DefaultCitationsPrompt = "Include citations to the source document with document name and link if document name and link is available.";
54	
55	    private readonly ProviderSessionState<TextSearchProviderState> _sessionState;
56	    private IReadOnlyList<string>? _stateKeys;
57	    private readonly Func<string, CancellationToken, Task<IEnumerable<TextSearchResult>>> _searchAsync;
58	    private readonly ILogger<TextSearchProvider>? _logger;
59	    private readonly AITool[] _tools;
60	    private readonly List<ChatRole> _recentMessageRolesIncluded;
61	    private readonly int _recentMessageMemoryLimit;
62	    private readonly TextSearchProviderOptions.TextSearchBehavior _searchTime;
63	    private readonly string _contextPrompt;
64	    private readonly string _citationsPrompt;
65	    private readonly Func<IList<TextSearchResult>, string>? _contextFormatter;
66	    private readonly Redactor _redactor;
67	
68	    /// <summary>
69	    /// Initializes a new instance of the <see cref="TextSearchProvider"/> class.
70	    /// </summary>
71	    /// <param name="searchAsync">Delegate that executes the search logic. Must not be <see langword="null"/>.</param>
72	    /// <param name="options">Optional configuration options.</param>
73	    /// <param name="loggerFactory">Optional logger factory.</param>
74	    /// <exception cref="ArgumentNullException">Thrown when <paramref name="searchAsync"/> is <see langword="null"/>.</exception>
75	    public TextSearchProvider(
76	        Func<string, CancellationToken, Task<IEnumerable<TextSearchResult>>> searchAsync,
77	        TextSearchProviderOptions? options = null,
78	        ILoggerFactory? loggerFactory = null)
79	        : base(options?.SearchInputMessageFilter, options?.StorageInputRequestMessageFilter, options?.StorageInputResponseMessageFilter)
80	    {
81	        this._sessionState = new ProviderSessionState<TextSearchProviderState>(
82	            _ => new TextSearchProviderState(),
83	            options?.StateKey ?? this.GetType().Name,
84	            AgentJsonUtilities.DefaultOptions);
85	        // Validate and assign parameters
86	        this._searchAsync = Throw.IfNull(searchAsync);
87	        this._logger = loggerFactory?.CreateLogger<TextSearchProvider>();
88	        this._recentMessageMemoryLimit = Throw.IfLessThan(options?.RecentMessageMemoryLimit ?? 0, 0);
89	        this._recentMessageRolesIncluded = options?.RecentMessageRolesIncluded ?? [ChatRole.User];
90	        this._searchTime = options?.SearchTime ?? TextSearchProviderOptions.TextSearchBehavior.BeforeAIInvoke;
91	        this._contextPrompt = options?.ContextPrompt ?? DefaultContextPrompt;
92	        this._citationsPrompt = options?.CitationsPrompt ?? DefaultCitationsPrompt;
93	        this._contextFormatter = options?.ContextFormatter;
94	        this._redactor = options?.EnableSensitiveTelemetryData == true ? NullRedactor.Instance : (options?.Redactor ?? new ReplacingRedactor("<redacted>"));
95	
96	        // Create the on-demand search tool (only used if behavior is OnDemandFunctionCalling)
97	        this._tools =
98	        [
99	            AIFunctionFactory.Create(
100	                this.SearchAsync,
101	                name: options?.FunctionToolName ?? DefaultPluginSearchFunctionName,
102	                description: options?.FunctionToolDescription ?? DefaultPluginSearchFunctionDescription)
103	        ];
104	    }
105	
106	    /// <inheritdoc />
107	    public override IReadOnlyList<string> StateKeys => this._stateKeys ??= [this._sessionState.StateKey];
108	
109	    /// <inheritdoc />
110	    protected override async ValueTask<AIContext> ProvideAIContextAsync(AIContextProvider.InvokingContext context, CancellationToken cancellationToken = default)
111	    {
112	        if (this._searchTime != TextSearchProviderOptions.TextSearchBehavior.BeforeAIInvoke)
113	        {
114	            // Expose the search tool for on-demand invocation.
115	            return new AIContext
116	            {
117	                Tools = this._tools
118	            };
119	        }
120	
121	        return new AIContext
122	        {
123	            Messages = await this.ProvideMessagesAsync(
124	                new InvokingContext(context.Agent, context.Session, context.AIContext.Messages ?? []),
125	                cancellationToken).ConfigureAwait(false)
126	        };
127	    }
128	
