11	/// <summary>
12	/// Provides a thread-safe key-value store for managing session-scoped state with support for type-safe access and JSON
13	/// serialization options.
14	/// </summary>
15	/// <remarks>
16	/// SessionState enables storing and retrieving objects associated with a session using string keys.
17	/// Values can be accessed in a type-safe manner and are serialized or deserialized using configurable JSON serializer
18	/// options. This class is designed for concurrent access and is safe to use across multiple threads.
19	/// </remarks>
20	[JsonConverter(typeof(AgentSessionStateBagJsonConverter))]
21	public class AgentSessionStateBag
22	{
23	    private readonly ConcurrentDictionary<string, AgentSessionStateBagValue> _state;
24	
25	    /// <summary>
26	    /// Initializes a new instance of the <see cref="AgentSessionStateBag"/> class.
27	    /// </summary>
28	    public AgentSessionStateBag()
29	    {
30	        this._state = new ConcurrentDictionary<string, AgentSessionStateBagValue>();
31	    }
32	
33	    /// <summary>
34	    /// Initializes a new instance of the <see cref="AgentSessionStateBag"/> class.
35	    /// </summary>
36	    /// <param name="state">The initial state dictionary.</param>
37	    internal AgentSessionStateBag(ConcurrentDictionary<string, AgentSessionStateBagValue>? state)
38	    {
39	        this._state = state ?? new ConcurrentDictionary<string, AgentSessionStateBagValue>();
40	    }
41	
42	    /// <summary>
43	    /// Gets the number of key-value pairs contained in the session state.
44	    /// </summary>
45	    public int Count => this._state.Count;
46	
47	    /// <summary>
48	    /// Tries to get a value from the session state.
49	    /// </summary>
50	    /// <typeparam name="T">The type of the value to retrieve.</typeparam>
51	    /// <param name="key">The key from which to retrieve the value.</param>
52	    /// <param name="value">The value if found and convertible to the required type; otherwise, null.</param>
53	    /// <param name="jsonSerializerOptions">The JSON serializer options to use for serializing/deserializing the value.</param>
54	    /// <returns><see langword="true"/> if the value was successfully retrieved, <see langword="false"/> otherwise.</returns>
55	    public bool TryGetValue<T>(string key, out T? value, JsonSerializerOptions? jsonSerializerOptions = null)
56	        where T : class
57	    {
58	        _ = Throw.IfNullOrWhitespace(key);
59	        var jso = jsonSerializerOptions ?? AgentAbstractionsJsonUtilities.DefaultOptions;
60	
61	        if (this._state.TryGetValue(key, out var stateValue))
62	        {
63	            return stateValue.TryReadDeserializedValue(out value, jso);
64	        }
65	
66	        value = null;
67	        return false;
68	    }
69	
70	    /// <summary>
71	    /// Gets a value from the session state.
72	    /// </summary>
73	    /// <typeparam name="T">The type of value to get.</typeparam>
74	    /// <param name="key">The key from which to retrieve the value.</param>
75	    /// <param name="jsonSerializerOptions">The JSON serializer options to use for serializing/deserialing the value.</param>
76	    /// <returns>The retrieved value or null if not found.</returns>
77	    /// <exception cref="InvalidOperationException">The value could not be deserialized into the required type.</exception>
78	    public T? GetValue<T>(string key, JsonSerializerOptions? jsonSerializerOptions = null)
79	        where T : class
80	    {
81	        _ = Throw.IfNullOrWhitespace(key);
82	        var jso = jsonSerializerOptions ?? AgentAbstractionsJsonUtilities.DefaultOptions;
83	
84	        if (this._state.TryGetValue(key, out var stateValue))
85	        {
86	            return stateValue.ReadDeserializedValue<T>(jso);
87	        }
88	
89	        return null;
90	    }
91	
92	    /// <summary>
93	    /// Sets a value in the session state.
94	    /// </summary>
95	    /// <typeparam name="T">The type of the value to set.</typeparam>
96	    /// <param name="key">The key to store the value under.</param>
97	    /// <param name="value">The value to set.</param>
98	    /// <param name="jsonSerializerOptions">The JSON serializer options to use for serializing the value.</param>
99	    public void SetValue<T>(string key, T? value, JsonSerializerOptions? jsonSerializerOptions = null)
100	        where T : class
101	    {
102	        _ = Throw.IfNullOrWhitespace(key);
103	        var jso = jsonSerializerOptions ?? AgentAbstractionsJsonUtilities.DefaultOptions;
104	
105	        var stateValue = this._state.GetOrAdd(key, _ =>
106	            new AgentSessionStateBagValue(value, typeof(T), jso));
107	
108	        stateValue.SetDeserialized(value, typeof(T), jso);
109	    }
110	
111	    /// <summary>
112	    /// Tries to remove a value from the session state.
113	    /// </summary>
114	    /// <param name="key">The key of the value to remove.</param>
115	    /// <returns><see langword="true"/> if the value was successfully removed; otherwise, <see langword="false"/>.</returns>
116	    public bool TryRemoveValue(string key)
117	        => this._state.TryRemove(Throw.IfNullOrWhitespace(key), out _);
118	
119	    /// <summary>
120	    /// Serializes all session state values to a JSON object.
121	    /// </summary>
122	    /// <returns>A <see cref="JsonElement"/> representing the serialized session state.</returns>
123	    /// <exception cref="InvalidOperationException">Thrown when a session state value is not properly initialized.</exception>
124	    public JsonElement Serialize()
125	    {
126	        return JsonSerializer.SerializeToElement(this._state, AgentAbstractionsJsonUtilities.DefaultOptions.GetTypeInfo(typeof(ConcurrentDictionary<string, AgentSessionStateBagValue>)));
127	    }
128	
129	    /// <summary>
130	    /// Deserializes a JSON object into an <see cref="AgentSessionStateBag"/> instance.
131	    /// </summary>
132	    /// <param name="jsonElement">The element to deserialize.</param>
133	    /// <returns>The deserialized <see cref="AgentSessionStateBag"/>.</returns>
134	    public static AgentSessionStateBag Deserialize(JsonElement jsonElement)
135	    {
136	        if (jsonElement.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null)
137	        {
138	            return new AgentSessionStateBag();
139	        }
140	
141	        return new AgentSessionStateBag(
142	            jsonElement.Deserialize(AgentAbstractionsJsonUtilities.DefaultOptions.GetTypeInfo(typeof(ConcurrentDictionary<string, AgentSessionStateBagValue>))) as ConcurrentDictionary<string, AgentSessionStateBagValue>
143	            ?? new ConcurrentDictionary<string, AgentSessionStateBagValue>());
144	    }
145	}
