3	using System;
4	using System.Text.Json;
5	using Microsoft.Shared.Diagnostics;
6	
7	namespace Microsoft.Agents.AI;
8	
9	/// <summary>
10	/// Provides strongly-typed state management for providers, enabling reading and writing of provider-specific state
11	/// to and from an <see cref="AgentSession"/>'s <see cref="AgentSessionStateBag"/>.
12	/// </summary>
13	/// <typeparam name="TState">The type of the state to be maintained. Must be a reference type.</typeparam>
14	/// <remarks>
15	/// <para>
16	/// This class encapsulates the logic for initializing, retrieving, and persisting provider state in the session's StateBag
17	/// using a configurable key and JSON serialization options. It is intended to be used as a composed field within provider
18	/// implementations (e.g., <see cref="AIContextProvider"/> or <see cref="ChatHistoryProvider"/> subclasses) to avoid
19	/// duplicating state management logic across provider type hierarchies.
20	/// </para>
21	/// <para>
22	/// State is stored in the <see cref="AgentSession.StateBag"/> using the <see cref="StateKey"/> property as the key,
23	/// enabling multiple providers to maintain independent state within the same session.
24	/// </para>
25	/// </remarks>
26	public class ProviderSessionState<TState>
27	    where TState : class
28	{
29	    private readonly Func<AgentSession?, TState> _stateInitializer;
30	    private readonly JsonSerializerOptions _jsonSerializerOptions;
31	
32	    /// <summary>
33	    /// Initializes a new instance of the <see cref="ProviderSessionState{TState}"/> class.
34	    /// </summary>
35	    /// <param name="stateInitializer">A function to initialize the state when it is not yet present in the session's StateBag.</param>
36	    /// <param name="stateKey">The key used to store the state in the session's StateBag.</param>
37	    /// <param name="jsonSerializerOptions">Options for JSON serialization and deserialization of the state.</param>
38	    public ProviderSessionState(
39	        Func<AgentSession?, TState> stateInitializer,
40	        string stateKey,
41	        JsonSerializerOptions? jsonSerializerOptions = null)
42	    {
43	        this._stateInitializer = Throw.IfNull(stateInitializer);
44	        this.StateKey = Throw.IfNullOrWhitespace(stateKey);
45	        this._jsonSerializerOptions = jsonSerializerOptions ?? AgentAbstractionsJsonUtilities.DefaultOptions;
46	    }
47	
48	    /// <summary>
49	    /// Gets the key used to store the provider state in the <see cref="AgentSession.StateBag"/>.
50	    /// </summary>
51	    public string StateKey { get; }
52	
53	    /// <summary>
54	    /// Gets the state from the session's StateBag, or initializes it using the state initializer if not present.
55	    /// </summary>
56	    /// <param name="session">The agent session containing the StateBag.</param>
57	    /// <returns>The provider state.</returns>
58	    public TState GetOrInitializeState(AgentSession? session)
59	    {
60	        if (session?.StateBag.TryGetValue<TState>(this.StateKey, out var state, this._jsonSerializerOptions) is true && state is not null)
61	        {
62	            return state;
63	        }
64	
65	        state = this._stateInitializer(session);
66	        if (session is not null)
67	        {
68	            session.StateBag.SetValue(this.StateKey, state, this._jsonSerializerOptions);
69	        }
70	
71	        return state;
72	    }
73	
74	    /// <summary>
75	    /// Saves the specified state to the session's StateBag using the configured state key and JSON serializer options.
76	    /// If the session is null, this method does nothing.
77	    /// </summary>
78	    /// <param name="session">The agent session containing the StateBag.</param>
79	    /// <param name="state">The state to be saved.</param>
80	    public void SaveState(AgentSession? session, TState state)
81	    {
82	        if (session is not null)
83	        {
84	            session.StateBag.SetValue(this.StateKey, state, this._jsonSerializerOptions);
85	        }
86	    }
87	}
