/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents the ability to maintain a persistent todo list
/// within an <see cref="AgentSession"/>.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five tools to the model — <c>AddTodos</c>, <c>CompleteTodos</c>, <c>RemoveTodos</c>,
/// <c>GetRemainingTodos</c>, and <c>GetAllTodos</c> — that allow an agent to plan and track multi-step work.
/// </para>
/// <para>
/// State is persisted in the session's <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c>,
/// so that todo items added during one invocation remain available in subsequent invocations on the same session.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    /// <summary>The key under which the todo state is stored in the session's state bag.</summary>
    internal const string StateKeyName = "TodoProvider";

    private const string InstructionsPrompt =
        "You have access to a persistent todo list to help you plan and track multi-step work. " +
        "Use the AddTodos tool to record tasks you intend to perform, CompleteTodos to mark tasks as done as you finish them, " +
        "RemoveTodos to delete tasks that are no longer relevant, GetRemainingTodos to review outstanding work, " +
        "and GetAllTodos to review the full list. Keep the todo list up to date as you work.";

    private readonly ProviderSessionState<TodoState> _sessionState;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            StateKeyName,
            AgentJsonUtilities.DefaultOptions);
    }

