    protected override ValueTask<AIContext> ProvideAIContextAsync(InvokingContext context, CancellationToken cancellationToken = default)
    {
        var session = context.Session;

        AITool[] tools =
        [
            AIFunctionFactory.Create(
                (List<TodoItemInput> todos) => this.AddTodos(session, todos),
                new AIFunctionFactoryOptions
                {
                    Name = "AddTodos",
                    Description = "Adds one or more new items to the todo list. Each item is assigned an auto-incrementing integer id.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.CompleteTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "CompleteTodos",
                    Description = "Marks the todo items with the given ids as complete. Returns the number of items that were found and marked complete.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.RemoveTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "RemoveTodos",
                    Description = "Removes the todo items with the given ids from the list. Returns the number of items removed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetRemainingTodos(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetRemainingTodos",
                    Description = "Gets the todo items that have not yet been completed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetAllTodosList(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetAllTodos",
                    Description = "Gets all todo items regardless of whether they have been completed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
        ];

        return new ValueTask<AIContext>(new AIContext
        {
            Instructions = InstructionsPrompt,
            Tools = tools,
        });
    }

    /// <summary>
    /// Gets all todo items associated with the specified session.
    /// </summary>
    /// <param name="session">The session whose todo items should be returned.</param>
    /// <returns>A read-only list of all todo items. Returns an empty list for a session with no todo state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this.GetAllTodosList(session);

    /// <summary>
    /// Gets the todo items associated with the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose remaining todo items should be returned.</param>
    /// <returns>A list of todo items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
    {
        var state = this._sessionState.GetOrInitializeState(session);
        return state.Items.Where(item => !item.IsComplete).ToList();
    }

    private List<TodoItem> GetAllTodosList(AgentSession? session)
    {
        var state = this._sessionState.GetOrInitializeState(session);
        return state.Items.ToList();
    }

    private List<TodoItem> AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this._sessionState.GetOrInitializeState(session);

